#:sdk Microsoft.NET.Sdk.Web #:package System.Threading.Tasks.Dataflow@8.0.0 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Threading.Tasks.Dataflow;  public class TaskDistributor {     private readonly TransformManyBlock<TaskBatch, TaskItem> _splitter;     private readonly TransformBlock<TaskItem, TaskResult> _workerBlock;     private readonly BatchBlock<TaskResult> _batchBlock;     private readonly ActionBlock<TaskResult[]> _aggregator;      public TaskDistributor()     {         var options = new ExecutionDataflowBlockOptions         {             BoundedCapacity = 10000,             MaxDegreeOfParallelism = Environment.ProcessorCount,             EnsureOrdered = false         };          _splitter = new TransformManyBlock<TaskBatch, TaskItem>(batch => batch.Items);         _workerBlock = new TransformBlock<TaskItem, TaskResult>(item =>         {             // 工作单元处理逻辑             return new TaskResult(item);         }, options);          _batchBlock = new BatchBlock<TaskResult>(100);         _aggregator = new ActionBlock<TaskResult[]>(results =>         {             // 结果聚合逻辑         });          _splitter.LinkTo(_workerBlock);         _workerBlock.LinkTo(_batchBlock);         _batchBlock.LinkTo(_aggregator);     } }  public record TaskBatch(List<TaskItem> Items); public record TaskItem(string Id); public record TaskResult(TaskItem Item);
